    // Parse URL parameters
    var currentScript = document.currentScript;
    var url = currentScript ? currentScript.src : '';
    var params = {};
    if (url && url.indexOf('?') > -1) {
        var query = url.split('?')[1];
        var pairs = query.split('&');
        for (var i = 0; i < pairs.length; i++) {
            var pair = pairs[i].split('=');
            params[decodeURIComponent(pair[0])] = decodeURIComponent(pair[1] || '');
        }
    }

    // Failsafe: Fallback to global variables if params are missing
    // We check if variable exists AND is not the raw macro string
    if (!params.click && typeof clickUrl !== 'undefined' && clickUrl.indexOf('%%') === -1) params.click = clickUrl;
    if (!params.click && typeof clickTag !== 'undefined' && clickTag.indexOf('%%') === -1) params.click = clickTag;
    if (!params.cachebuster && typeof cacheBuster !== 'undefined' && cacheBuster.indexOf('%%') === -1) params.cachebuster = cacheBuster;
    if (!params.renderingMode && typeof renderingMode !== 'undefined' && renderingMode.indexOf('%%') === -1) params.renderingMode = renderingMode;

    // Custom Trackers Failsafe
    if (!params.customClick && typeof customClick !== 'undefined' && customClick.indexOf('%%') === -1 && customClick.indexOf('http') === 0) {
        params.customClick = customClick;
    }

    // Collect additional trackers
    params.trackers = [];
    if (typeof tracker1 !== 'undefined' && tracker1.indexOf('%%') === -1 && tracker1.indexOf('http') === 0) params.trackers.push(tracker1);
    if (typeof tracker2 !== 'undefined' && tracker2.indexOf('%%') === -1 && tracker2.indexOf('http') === 0) params.trackers.push(tracker2);
    if (typeof tracker3 !== 'undefined' && tracker3.indexOf('%%') === -1 && tracker3.indexOf('http') === 0) params.trackers.push(tracker3);


    // Standard GAM Macro Replacement
    if (params.click) content = content.replace(/%%CLICK_URL_UNESC%%/g, params.click);
    if (params.cachebuster) content = content.replace(/%%CACHEBUSTER%%/g, params.cachebuster);
    
    // Replace custom trackers if present in content
    if (params.customClick) content = content.replace(/%%CUSTOM_CLICK%%/g, params.customClick);

    // Generic Macro Replacement (%%KEY%% -> value)
    for (var key in params) {
        var macro = '%%' + key.toUpperCase() + '%%';
        var regex = new RegExp(macro, 'g');
        content = content.replace(regex, params[key]);
    }

    // Write to document
